const W=api.w,H=api.h,cx=W/2,cy=H/2;
const k=api.ease(api.seg(t,0,4));
api.cam(0,0,api.lerp(1,1.6,k),k*0.3);
for(let i=0;i<40;i++){
  const a=i/40*6.283+t*0.5, r=api.lerp(W*0.5,12,k)*(0.5+api.rand(i)*0.5);
  c.fillStyle=i%5==0?'#ff6a3d':'#5ad1ff';
  c.globalAlpha=0.3+0.5*api.rand(i+9);
  c.beginPath();c.arc(cx+Math.cos(a)*r*1.2,cy+Math.sin(a)*r*1.2,2+api.rand(i+3)*3,0,6.283);c.fill();
}
c.globalAlpha=1;
api.cam(0,0,1,0);
api.say("What is everything made of?",0.4,3.8);

const W=api.w,H=api.h,cx=W/2,cy=H/2;
const k=api.ease(api.seg(t,0,6));
const z=Math.pow(10,k*1.5);
api.cam(0,0,1,0);
const g=c.createRadialGradient(cx,cy,0,cx,cy,W*0.6);
g.addColorStop(0,'rgba(90,209,255,0.25)');g.addColorStop(1,'rgba(0,0,0,0)');
c.fillStyle=g;c.fillRect(0,0,W,H);
c.strokeStyle='#5ad1ff';c.lineWidth=1.5;
for(let i=0;i<4;i++){
  const s=((i/4+k*1.2)%1);
  const r=12+s*s*W*0.9;
  c.globalAlpha=Math.sin(s*3.14159)*0.8;
  api.path(api.pts.poly(48,i%2?6:3+i,r).map(p=>[cx+p[0],cy+p[1]]),true);c.stroke();
}
c.globalAlpha=1;
c.fillStyle='#ff6a3d';c.beginPath();c.arc(cx,cy,5+k*10,0,6.283);c.fill();
api.say(api.seg(t,0,1)>=0&&k<0.5?"Zoom in. And in.":"Smaller than atoms.",0.3,5.5);

const W=api.w,H=api.h,cx=W/2,cy=H/2;
const k=api.ease(api.seg(t,0,5));
const glow=c.createRadialGradient(cx,cy,0,cx,cy,90);
glow.addColorStop(0,'rgba(255,106,61,0.6)');glow.addColorStop(1,'rgba(255,106,61,0)');
c.fillStyle=glow;c.fillRect(cx-100,cy-100,200,200);
c.fillStyle='#ff6a3d';c.beginPath();c.arc(cx,cy,10,0,6.283);c.fill();
const m=api.seg(t,2,5);
const ring=api.morph(api.pts.circle(60,10+m*0),api.pts.circle(60,10+m*0),0);
c.strokeStyle='#ffd0bd';c.lineWidth=2;
c.globalAlpha=m;
api.path(api.pts.circle(60,10+m*60).map(p=>[cx+p[0],cy+p[1]]),true);c.stroke();
c.globalAlpha=1;
api.say("Scientists guess: not dots.",0.3,4.7);

const W=api.w,H=api.h,cx=W/2,cy=H/2;
const k=api.ease(api.seg(t,0,2.5));
const a=api.lerp(0,W*0.38,k);
const ring=api.pts.circle(80,70*(1-k)+10).map(p=>[cx+p[0],cy+p[1]]);
const line=api.pts.wave(80,W*0.8,6+Math.sin(t*4)*6,t*3).map(p=>[cx-W*0.4+p[0],cy+p[1]]);
c.strokeStyle='#ff6a3d';c.lineWidth=4;c.shadowColor='#ff6a3d';c.shadowBlur=16;
api.path(api.morph(ring,line,k),false);c.stroke();
c.shadowBlur=0;
api.say("Tiny wiggling strings.",0.4,5.6);

const W=api.w,H=api.h,cx=W/2,cy=H/2;
const cols=['#5ad1ff','#7a8cff','#ff6a3d'];
for(let i=0;i<3;i++){
  const y=cy-130+i*130, n=i+1;
  const pts=api.pts.wave(80,W*0.8,28+8*Math.sin(t*2+i),t*(2+i)).map(p=>[cx-W*0.4+p[0],y+p[1]*Math.sin(n*3.14159*(p[0]/(W*0.8)+0.0001))*0+Math.sin(n*3.14159*p[0]/(W*0.8))*20*Math.sin(t*(3+i))]);
  c.strokeStyle=cols[i];c.lineWidth=3;c.shadowColor=cols[i];c.shadowBlur=12;
  api.path(pts,false);c.stroke();
}
c.shadowBlur=0;
api.say("Each wiggle is a note.",0.3,6.6);

const W=api.w,H=api.h,cx=W/2,cy=H/2;
const k=api.seg(t,0,6);
const names=['#5ad1ff','#7a8cff','#ff6a3d'];
for(let i=0;i<3;i++){
  const ang=i/3*6.283+t*0.6, r=80+Math.sin(t*1.5+i)*10;
  const x=cx+Math.cos(ang)*r,y=cy+Math.sin(ang)*r;
  const g=c.createRadialGradient(x,y,0,x,y,40);
  g.addColorStop(0,names[i]);g.addColorStop(1,'rgba(0,0,0,0)');
  c.fillStyle=g;c.globalAlpha=0.9;c.fillRect(x-40,y-40,80,80);
  c.globalAlpha=1;c.fillStyle='#fff';c.beginPath();c.arc(x,y,4,0,6.283);c.fill();
}
api.say(k<0.5?"Different note, different particle.":"Light. Electrons. Quarks.",0.3,5.7);

const W=api.w,H=api.h,cx=W/2,cy=H/2;
const k=api.ease(api.seg(t,0,5));
api.cam(0,0,api.lerp(1,0.4,k),0);
for(let i=0;i<60;i++){
  const a=api.rand(i)*6.283, r=api.rand(i+50)*W*1.2;
  c.fillStyle=i%7==0?'#ff6a3d':'#5ad1ff';
  c.globalAlpha=0.5;
  c.beginPath();c.arc(cx+Math.cos(a)*r*0.6,cy+Math.sin(a)*r*0.6,2+api.rand(i)*2,0,6.283);c.fill();
}
c.globalAlpha=1;
api.cam(0,0,1,0);
c.fillStyle='#ff6a3d';c.beginPath();c.arc(cx,cy,6,0,6.283);c.fill();
api.say("One string. Everything.",0.4,4.6);
